/**
 * Cloudflare Worker entry: the OpenNext app plus a daily cron for partner balance reminders.
 * Cron times are UTC; 07:00 and 08:00 cover 8am UK time in both BST and GMT (see wrangler.jsonc).
 */
// .open-next/ is generated by `opennextjs-cloudflare build`, so this file is left out of tsconfig
import handler from "./.open-next/worker.js";

type Env = Record<string, unknown>;
type Ctx = { waitUntil(p: Promise<unknown>): void };

const worker = {
  fetch: handler.fetch,
  async scheduled(_event: unknown, env: Env, ctx: Ctx) {
    const req = new Request("https://cricket.hillrisers.co.uk/api/partners/reminders", { method: "POST" });
    ctx.waitUntil(
      handler.fetch(req, env, ctx).then(async (res: Response) => console.log("[hillrisers] reminders", res.status, await res.text())),
    );
  },
};

export default worker;
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
